// `area`'s caller contract, read in this module, where it is defined,
// however the modules are ordered (`index.ts` forwards into it).
export const area = (who: string, width: i32, height: i32): i32 => {
  if (width < 0 || height < 0) {
    panic(`${who}: a negative size`)
  }
  const size: i64 = toI64(width) * toI64(height)
  if (size > toI64(2147483647)) {
    panic(`${who}: more than 2^31 - 1 cells`)
  }
  return toI32(size)
}
